WITH warehouse_date_loss AS ( SELECT w.w_warehouse_id, w.w_warehouse_name, wr.wr_returned_date_sk AS return_date_key, SUM(wr.wr_net_loss) AS total_net_loss FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN inventory inv ON i.i_item_sk = inv.inv_item_sk JOIN warehouse w ON inv.inv_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_warehouse_id, w.w_warehouse_name, wr.wr_returned_date_sk ) SELECT wdl.w_warehouse_id, wdl.w_warehouse_name, wdl.return_date_key, wdl.total_net_loss, CASE WHEN wdl.total_net_loss > 100000 THEN 'Critical' WHEN wdl.total_net_loss > 50000 THEN 'High' WHEN wdl.total_net_loss > 10000 THEN 'Medium' ELSE 'Low' END AS loss_category, DENSE_RANK() OVER (PARTITION BY wdl.return_date_key ORDER BY wdl.total_net_loss DESC) AS loss_rank FROM warehouse_date_loss wdl WHERE wdl.total_net_loss > 0 ORDER BY wdl.return_date_key DESC, loss_rank
